  98	export function createResultWatcher(
  99		pi: { events: IntercomEventBus },
 100		state: SubagentState,
 101		resultsDir: string,
 102		completionTtlMs: number,
 103		deps: ResultWatcherDeps = {},
 104	): {
 105		startResultWatcher: () => void;
 106		primeExistingResults: () => void;
 107		stopResultWatcher: () => void;
 108	} {
 109		const fsApi = deps.fs ?? fs;
 110		const timers = deps.timers ?? { setTimeout, clearTimeout, setInterval, clearInterval };
 111	
 112		const handleResult = async (file: string) => {
 113			const resultPath = path.join(resultsDir, file);
 114			if (!fsApi.existsSync(resultPath)) return;
 115			try {
 116				const data = JSON.parse(fsApi.readFileSync(resultPath, "utf-8")) as ResultFileData;
 117				if (typeof data.sessionId !== "string" || data.sessionId !== state.currentSessionId) return;
 118	
 119				const runId = data.runId ?? data.id ?? file.replace(/\.json$/i, "");
 120				const hasExplicitNestedChildren = data.nestedChildren !== undefined;
 121				let nestedChildren = compactNestedResultChildren(sanitizeNestedResultChildren(data.nestedChildren, resultPath, "nestedChildren"));
 122				if (!nestedChildren?.length && !hasExplicitNestedChildren) {
 123					try {
 124						nestedChildren = compactNestedResultChildren(projectNestedRegistryForRoot(runId)?.children);
 125					} catch (error) {
 126						console.error(`Failed to enrich subagent result file '${resultPath}' with nested registry children; will retry later:`, error);
 127						return;
 128					}
 129				}
 130				const now = Date.now();
 131				const completionKey = buildCompletionKey(data, `result:${file}`);
 132				if (markSeenWithTtl(state.completionSeen, completionKey, now, completionTtlMs)) {
 133					fsApi.unlinkSync(resultPath);
 134					return;
 135				}
 136	
 137				const hasResultChildren = Array.isArray(data.results) && data.results.length > 0;
 138				const resultChildren = hasResultChildren
 139					? data.results!
 140					: [{
 141						agent: data.agent,
 142						output: data.summary,
 143						success: data.success,
 144					}];
 145				const normalizedChildren = attachNestedChildrenToResultChildren(runId, resultChildren.map((result = {}, index): SubagentResultIntercomChild => {
 146					const baseOutput = result.output ?? data.summary;
 147					const hasRealOutput = typeof baseOutput === "string" && baseOutput.trim().length > 0;
 148					const output = hasRealOutput ? baseOutput : "(no output)";
 149					const summary = result.success === false && result.error
 150						? `${result.error}${hasRealOutput ? `\n\nOutput:\n${baseOutput}` : ""}`
 151						: output;
 152					const sessionPath = result.sessionFile ?? (resultChildren.length === 1 ? data.sessionFile : undefined);
 153					const childNestedChildren = sanitizeNestedResultChildren(result.children, resultPath, `results[${index}].children`);
 154					const childState = result.state === "paused" || result.state === "stopped"
 155						? result.state
 156						: result.stopped === true
 157							? "stopped"
 158							: data.state === "paused" || (!hasResultChildren && (data.state === "stopped" || typeof result.success !== "boolean"))
 159								? data.state
 160								: undefined;
 161					return {
 162						agent: result.agent ?? data.agent ?? `step-${index + 1}`,
 163						status: resolveSubagentResultStatus({
 164							success: result.success,
 165							state: childState,
 166						}),
 167						summary,
 168						index,
 169						artifactPath: result.artifactPaths?.outputPath,
 170						...(typeof sessionPath === "string" && fsApi.existsSync(sessionPath) ? { sessionPath } : {}),
 171						...(result.intercomTarget ? { intercomTarget: result.intercomTarget } : {}),
 172						...(childNestedChildren ? { children: childNestedChildren } : {}),
 173					};
 174				}), nestedChildren);
