  22	function waitSync(delayMs: number): void {
  23		if (delayMs <= 0) return;
  24		if (WAIT_VIEW) {
  25			try {
  26				// writeAtomicJson is synchronous because callers often update status from sync callbacks.
  27				// Atomics.wait gives Windows rename locks time to clear without burning CPU.
  28				Atomics.wait(WAIT_VIEW, 0, 0, delayMs);
  29				return;
  30			} catch {
  31				// Fall through to the portable busy wait below.
  32			}
  33		}
  34		const end = Date.now() + delayMs;
  35		while (Date.now() < end) {
  36			// Portable fallback for runtimes where Atomics.wait is unavailable.
  37		}
  38	}
  39	
  40	function isRetryableRenameError(error: unknown): boolean {
  41		const code = (error as NodeJS.ErrnoException | undefined)?.code;
  42		return typeof code === "string" && RETRYABLE_RENAME_ERROR_CODES.has(code);
  43	}
  44	
  45	function renameWithRetry(
  46		fsImpl: AtomicJsonFs,
  47		sourcePath: string,
  48		targetPath: string,
  49		retryDelaysMs: readonly number[],
  50		wait: (delayMs: number) => void,
  51	): void {
  52		for (let attempt = 0; ; attempt++) {
  53			try {
  54				fsImpl.renameSync(sourcePath, targetPath);
  55				return;
  56			} catch (error) {
  57				const delayMs = retryDelaysMs[attempt];
  58				if (delayMs === undefined || !isRetryableRenameError(error)) throw error;
  59				wait(delayMs);
  60			}
  61		}
  62	}
