  64	export function createAtomicJsonWriter(options: AtomicJsonWriterOptions = {}): (filePath: string, payload: object) => void {
  65		const fsImpl = options.fs ?? fs;
  66		const now = options.now ?? Date.now;
  67		const pid = options.pid ?? process.pid;
  68		const random = options.random ?? Math.random;
  69		const mode = options.mode;
  70		const retryRenameErrors = options.retryRenameErrors ?? process.platform === "win32";
  71		const retryDelaysMs = retryRenameErrors ? options.retryDelaysMs ?? DEFAULT_RENAME_RETRY_DELAYS_MS : [];
  72		const wait = options.wait ?? waitSync;
  73		return (filePath: string, payload: object): void => {
  74			fsImpl.mkdirSync(path.dirname(filePath), { recursive: true });
  75			const tempPath = path.join(
  76				path.dirname(filePath),
  77				`.${path.basename(filePath)}.${pid}.${now()}.${random().toString(36).slice(2)}.tmp`,
  78			);
  79			try {
  80				fsImpl.writeFileSync(tempPath, JSON.stringify(payload, null, 2), mode === undefined ? "utf-8" : { encoding: "utf-8", mode });
  81				renameWithRetry(fsImpl, tempPath, filePath, retryDelaysMs, wait);
  82			} finally {
  83				fsImpl.rmSync(tempPath, { force: true });
  84			}
  85		};
  86	}
